-- 3. Saving cells without trampling newer edits.
-- Each cell carries the moment it was edited ("at"). If the server already holds a *different* value written after that
-- moment (another device edited it meanwhile), the server value wins and is returned so the app can show it.
create function public.apply_cells(cells jsonb) returns jsonb
language plpgsql security invoker set search_path = public as $$
declare
  c jsonb;
  cur public.monthly_schedule%rowtype;
  rejected jsonb := '[]'::jsonb;
begin
  for c in select * from jsonb_array_elements(cells) loop
    select * into cur from public.monthly_schedule where staff_id = c->>'staff_id' and day = (c->>'day')::date;
    if found and cur.updated_at > (c->>'at')::timestamptz and cur.shift_code <> c->>'shift_code' then
      rejected := rejected || jsonb_build_array(jsonb_build_object('staff_id', cur.staff_id, 'day', cur.day, 'shift_code', cur.shift_code));
    else
      insert into public.monthly_schedule (staff_id, day, shift_code)
      values (c->>'staff_id', (c->>'day')::date, c->>'shift_code')
      on conflict (staff_id, day) do update set shift_code = excluded.shift_code;
    end if;
  end loop;
  return rejected;
end $$;

-- ===== migrations/0007_admin_access.sql =====
-- Access managed from the web: an admin invites e-mails; an invited person becomes an editor the first time she signs in.

alter table public.editors
  add column if not exists role text not null default 'editor' check (role in ('admin','editor')),
  add column if not exists email text;

-- Editors that existed before this migration keep working; the first admin is claimed from the app (see claim_access).
create table public.editor_invites (
  email text primary key check (email = lower(email)),
  role text not null default 'editor' check (role in ('admin','editor')),
  invited_by uuid references auth.users(id) default auth.uid(),
  invited_at timestamptz not null default now()
);

create function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.editors where user_id = auth.uid() and role = 'admin');
$$;

-- Called by the app right after signing in. Returns the access the person has: 'admin', 'editor' or 'none'.
--  * already an editor            -> keeps her role
--  * her e-mail was invited       -> becomes editor/admin as invited (the invitation is used up)
--  * nobody is admin yet          -> she becomes the first admin (whoever opens the app first after setup)
create function public.claim_access() returns text
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  mail text := lower(coalesce(auth.jwt() ->> 'email', ''));
  r text;
  inv public.editor_invites%rowtype;
begin
  if uid is null then return 'none'; end if;
  select role into r from public.editors where user_id = uid;
  if found then
    update public.editors set email = mail where user_id = uid and email is distinct from mail;
    return r;
  end if;
  select * into inv from public.editor_invites where email = mail;
  if found then
    insert into public.editors (user_id, email, role) values (uid, mail, inv.role);
    delete from public.editor_invites where email = mail;
    return inv.role;
  end if;
  if not exists (select 1 from public.editors where role = 'admin') then
    insert into public.editors (user_id, email, role) values (uid, mail, 'admin');
    return 'admin';
  end if;
  return 'none';
end $$;

-- Never leave the hotel without an admin.
create function public.keep_one_admin() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.role = 'admin' and (tg_op = 'DELETE' or new.role <> 'admin') and not exists (select 1 from public.editors where role = 'admin' and user_id <> old.user_id) then
    raise exception 'Tiene que quedar al menos una persona administradora';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;
create trigger editors_keep_one_admin before update or delete on public.editors for each row execute function public.keep_one_admin();

alter table public.editor_invites enable row level security;
create policy "admins manage invites" on public.editor_invites for all using (public.is_admin()) with check (public.is_admin());
create policy "admins read editors" on public.editors for select using (public.is_admin());
create policy "admins manage editors" on public.editors for all using (public.is_admin()) with check (public.is_admin());

-- ===== migrations/0008_workers.sql =====
-- Workers: people who can see the schedule (as everyone) and send their OWN requests, linked to one person of the team.

-- 1. roles: admin / editor / worker (+ the person of the team a worker is)
alter table public.editors drop constraint if exists editors_role_check;
alter table public.editors add constraint editors_role_check check (role in ('admin','editor','worker'));
alter table public.editors add column if not exists staff_id text references public.staff(id) on delete set null;
alter table public.editors add constraint editors_worker_has_staff check (role <> 'worker' or staff_id is not null) not valid;

alter table public.editor_invites drop constraint if exists editor_invites_role_check;
alter table public.editor_invites add constraint editor_invites_role_check check (role in ('admin','editor','worker'));
alter table public.editor_invites add column if not exists staff_id text references public.staff(id) on delete cascade;
alter table public.editor_invites add constraint invites_worker_has_staff check (role <> 'worker' or staff_id is not null);

-- 2. is_editor() now means "may change the schedule": admins and editors, never workers.
create or replace function public.is_editor() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.editors where user_id = auth.uid() and role in ('admin','editor'));
$$;

create function public.my_staff_id() returns text
language sql stable security definer set search_path = public as $$
  select staff_id from public.editors where user_id = auth.uid() and role = 'worker';
$$;

-- 3. claim_access also hands out the worker role (with the invited person of the team)
create or replace function public.claim_access() returns text
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  mail text := lower(coalesce(auth.jwt() ->> 'email', ''));
  r text;
  inv public.editor_invites%rowtype;
begin
  if uid is null then return 'none'; end if;
  select role into r from public.editors where user_id = uid;
  if found then
    update public.editors set email = mail where user_id = uid and email is distinct from mail;
    return r;
  end if;
  select * into inv from public.editor_invites where email = mail;
  if found then
    insert into public.editors (user_id, email, role, staff_id) values (uid, mail, inv.role, inv.staff_id);
    delete from public.editor_invites where email = mail;
    return inv.role;
  end if;
  if not exists (select 1 from public.editors where role = 'admin') then
    insert into public.editors (user_id, email, role) values (uid, mail, 'admin');
    return 'admin';
  end if;
  return 'none';
end $$;

-- 4. what a worker may do with requests: see, create and cancel (while pending) only her own
create policy "workers read own requests" on public.requests for select using (staff_id = public.my_staff_id());
create policy "workers create own requests" on public.requests for insert with check (
  staff_id = public.my_staff_id() and status = 'pending' and decided_at is null and decision_note is null
);
create policy "workers cancel own pending requests" on public.requests for delete using (staff_id = public.my_staff_id() and status = 'pending');

-- ===== migrations/0009_invite_links.sql =====
-- Invitation LINKS: the admin picks a role (and the person of the team for workers), gets a link and sends it by WhatsApp.
-- Whoever opens it creates her own account and gets exactly that access. The link works once and expires.

alter table public.editor_invites drop constraint editor_invites_pkey;
alter table public.editor_invites add column id uuid not null default gen_random_uuid();
alter table public.editor_invites add primary key (id);
alter table public.editor_invites alter column email drop not null;
create unique index editor_invites_email_key on public.editor_invites (email) where email is not null;
alter table public.editor_invites add column code text not null unique default replace(gen_random_uuid()::text, '-', '');
alter table public.editor_invites add column expires_at timestamptz not null default now() + interval '14 days';

-- What an invitation says (for the sign-up page, before the person has an account). Reveals no e-mail.
create function public.invite_info(_code text) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object('role', i.role, 'staff_name', s.name)
  from public.editor_invites i left join public.staff s on s.id = i.staff_id
  where i.code = _code and i.expires_at > now() and i.role in ('editor','worker');
$$;

-- The person (already signed in) uses the link: she gets the access of the invitation and the link is used up.
-- Returns 'worker' / 'editor', 'invalid' (unknown, used or expired) or 'already' (she already had access: nothing changes).
create function public.redeem_invite(_code text) returns text
language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  mail text := lower(coalesce(auth.jwt() ->> 'email', ''));
  inv public.editor_invites%rowtype;
begin
  if uid is null then return 'invalid'; end if;
  if exists (select 1 from public.editors where user_id = uid) then return 'already'; end if;
  select * into inv from public.editor_invites where code = _code and expires_at > now() and role in ('editor','worker');
  if not found then return 'invalid'; end if;
  insert into public.editors (user_id, email, role, staff_id) values (uid, mail, inv.role, inv.staff_id);
  delete from public.editor_invites where id = inv.id;
  return inv.role;
end $$;

